"""Derive SkyyMobs/build_skyymobs_0.1.19.py from the GENERATED SkyyMobs 0.1.18 (build_skyymobs_0.1.18.py = the SET pin, itself GENERATED by
tools/mobs_0_1_18_patch.py - edit the patch, never a generated script). Every anchor is asserted once; at the end every change is undone on a
copy and compared with 0.1.18 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/mobs_0_1_19_patch.py   then   python SkyyMobs/build_skyymobs_0.1.19.py   (never --deploy)
      then  python SkyyMobs/test_skyymobs_0.1.19.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G
import wc15 as WC

NOTE = '''0.1.19 (2026-10-24) = WEAPONCRAFT x1.5 (round wc15, FULL round with SkyyGear 0.3.45 + SkyyClasses 0.1.48; Accessory Plates HELD; tools/wc15.py). Decision
  (docs/answered/classes.md 2026-10-23 CLASS TREE REBUILD BUILT): "Weaponcraft (old Combat) per-rank numbers to be raised ~x1.5 in a follow-up
  Gear / Mobs / Pets / Accessories balance round (they give ~40-47 % of their old share at Lv 50 at 1 point a level)". Skyy 2026-10-24: "dont
  worry about usage, work through your whole list".
  1. THE FIVE SPOILS ROWS (Weaponcraft, the old Combat branch 3) per rank x1.5 (ceiling = per x max rank, x1.5 too): Scavenger 2 -> 3 % a rank
     (15 at rank 5), Coin Purse 3 -> 4.5 % (13.5), Rare Drop 1 -> 1.5 % (4.5), Boss Hunter 3 -> 4.5 % (13.5), Lucky Kill 2 -> 3 % (9). Keys,
     ranks, the rolls (never gear: SkyyGear's UT meter / Mythic roll see the same kills) and the Server Setup rows (Mobs -> Skill trees) are
     unchanged - only their defaults move. tools/trees_v3_effects.py is NOT edited (other builders import it): tools/wc15.py apply() swaps
     the five rows in memory right after this script imports the table, so V3P / V3X, loadV3's built-in numbers, V3_TEXT and the kit rows
     carry the new values.
  2. ONE-TIME UPDATE MobSpoils.migrateWc15 (PROJECT-RULES 4; generated by tools/wc15.py java(), the MobMig machinery's rules for
     trees.properties): an existing Skyy_SkyyMobs/trees.properties line still holding the 0.1.18 default (one plain line, the last entry of
     its key) moves to the new one; a custom value is kept + one INFO note; a missing line = the new built-in number. History copy first
     (verified), atomic write (ISO-8859-1, the file's own line endings), one config-changes.log line per moved line (Undo in Server Setup ->
     Changes), the marker comment last (a fresh 0.1.19 file carries it). setup(): after MobMigP4, before MobCfg.load / MobSpoils.loadV3.
  SAVED DATA: player data none; trees.properties as above. No command / system / class (the update lives in MobSpoils).
  ROLLBACK to 0.1.18: Undo the wc15 rows in Server Setup -> Changes first (0.1.18 would read the raised numbers as admin values and keep
  them); the marker comment is ignored. No floor of its own.
'''

P = G.Patch(os.path.join(ROOT, "SkyyMobs", "build_skyymobs_0.1.18.py"), os.path.join(ROOT, "SkyyMobs", "build_skyymobs_0.1.19.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.1.18"') and P.s.startswith('"""SkyyMobs 0.1.18 - build script') and P.has("MobEgg") and not P.has("migrateWc15"), "not the SET pin 0.1.18"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass(")

P.rep('''"""SkyyMobs 0.1.18 - build script (javassist via jpype). GENERATED by tools/mobs_0_1_18_patch.py from the SET pin 0.1.17 - edit the
patch, never this file. Run: python SkyyMobs/build_skyymobs_0.1.18.py -> SkyyMobs/SkyyMobs-0.1.18.jar (never --deploy).
Test: python SkyyMobs/test_skyymobs_0.1.18.py
''', '''"""SkyyMobs 0.1.19 - build script (javassist via jpype). GENERATED by tools/mobs_0_1_19_patch.py from the SET pin 0.1.18 - edit the
patch, never this file. Run: python SkyyMobs/build_skyymobs_0.1.19.py -> SkyyMobs/SkyyMobs-0.1.19.jar (never --deploy).
Test: python SkyyMobs/test_skyymobs_0.1.19.py
''' + NOTE + "\n")
P.rep('VERSION = "0.1.18"', 'VERSION = "0.1.19"')

# 1. the five Spoils rows x1.5, in memory, before anything is generated from the table
P.rep('''import trees_v3_effects as V3E
V3E.check()
''', '''import trees_v3_effects as V3E
V3E.check()
import wc15 as WC15
# 0.1.19 (wc15): the five Weaponcraft (Spoils) rows x1.5 (tools/wc15.py; 0 = the shared table already holds the new numbers)
_WC15_N = WC15.apply(V3E, "SkyyMobs")
assert _WC15_N in (0, 5) and [(_e[2], _e[5]) for _e in V3E.rows("SkyyMobs")] == [(_r[2], _r[5]) for _r in WC15.ROWS["SkyyMobs"]], "0.1.19: the Spoils rows"
print("0.1.19 wc15: %d Spoils rows x1.5 (%s)" % (len(WC15.ROWS["SkyyMobs"]), ", ".join("%s %s" % (_m[0], _m[2]) for _m in WC15.mig_rows(V3E, "SkyyMobs") if _m[0].endswith(".per"))))
''')

# 2. the one-time trees.properties update (after the kit's emit: it calls CfgFile / CfgRows / CfgHist / CfgLog)
P.rep('''# gear never comes from here (SkyyGear's UT / Mythic rates stay as P5 set them): weapons, armour, tools, shields, our own items''',
      '''# ---- 0.1.19 ONE-TIME UPDATE migrateWc15 (wc15; PROJECT-RULES section 4; tools/wc15.py java()): Skyy_SkyyMobs/trees.properties lines still on
# the 0.1.18 Spoils defaults -> x1.5 (custom values kept + noted), History copy verified first, one change-log line each (Undo in Server Setup
# -> Changes), the marker comment last (a fresh 0.1.19 file carries it)
_WCF, _WCM = WC15.java(V3E, "SkyyMobs", "MobLog", "@PKG@.MobLog.info", "@PKG@.MobLog.warn")
for _d in _WCF:
    F(msp, _d)
for _m in _WCM:
    M(msp, _m)
assert WC15.MARK_ID in V3E.cfg_text("SkyyMobs"), "0.1.19: a fresh trees.properties carries the wc15 marker"
# gear never comes from here (SkyyGear's UT / Mythic rates stay as P5 set them): weapons, armour, tools, shields, our own items''')
P.rep('''  if (mgp4.length() > 0) mg = mg.length() > 0 ? mg + "\\n" + mgp4 : mgp4;
''', '''  if (mgp4.length() > 0) mg = mg.length() > 0 ? mg + "\\n" + mgp4 : mgp4;
  String mwc = @PKG@.MobSpoils.migrateWc15(dir);   // 0.1.19 (wc15): trees.properties Spoils rows x1.5 - only the untouched 0.1.18 defaults (once; History first; Undo)
  if (mwc.length() > 0) mg = mg.length() > 0 ? mg + "\\n" + mwc : mwc;
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0, "0.1.19: no class / command / system"
_i = P.s.index
assert _i("_WC15_N = WC15.apply(") < _i("CFG_ROWS += V3E.cfg_rows(\"SkyyMobs\"") < _i("kit = CFG.emit(pool, PKG, MOD=MOD") < _i("_WCF, _WCM = WC15.java(")
assert _i("String mwc = @PKG@.MobSpoils.migrateWc15(dir);") < _i("  @PKG@.MobCfg.load();\n  String spt = @PKG@.MobSpoils.loadV3(dir);")
P.finish()
print("wrote", P.dst)
